from abc import ABC, abstractmethod
from app import db


class BaseRepository(ABC):
    def __init__(self, model):
        self.model = model

    def get_by_id(self, id):
        return self.model.query.get(id)

    def create(self, **kwargs):
        instance = self.model(**kwargs)
        db.session.add(instance)
        db.session.commit()
        return instance

    def update(self, id, **kwargs):
        instance = self.get_by_id(id)
        if not instance:
            return None
        for key, value in kwargs.items():
            if value is not None:
                setattr(instance, key, value)
        db.session.commit()
        return instance

    def delete(self, id):
        instance = self.get_by_id(id)
        if instance:
            db.session.delete(instance)
            db.session.commit()
            return True
        return False

    def get_all(self):
        return self.model.query.all()


class UserRepository(BaseRepository):
    def __init__(self):
        from app import User
        super().__init__(User)

    def get_by_username(self, username):
        return self.model.query.filter_by(username=username).first()

    def create_user(self, username, password_hash, email=None):
        user = self.model(username=username, password_hash=password_hash)
        if email:
            user.email = email
        db.session.add(user)
        db.session.commit()
        return user


class TaskRepository(BaseRepository):
    def __init__(self):
        from app import Task
        super().__init__(Task)

    def get_tasks_by_owner(self, owner_id):
        from app import Task
        return Task.query.filter_by(owner_id=owner_id).order_by(Task.created_at.desc()).all()

    def create_task(self, title, owner_id):
        task = self.model(title=title, owner_id=owner_id)
        db.session.add(task)
        db.session.commit()
        return task

